from colorama import Fore, Style, init
init(autoreset=True)

def info(msg):    print(Fore.CYAN + '[i] ' + msg)
def ok(msg):      print(Fore.GREEN + '[ok] ' + msg)
def warn(msg):    print(Fore.YELLOW + '[!] ' + msg)
def err(msg):     print(Fore.RED + Style.BRIGHT + '[x] ' + msg)

info('start')
ok('{{msg_var}} done')
warn('disk near full')
err('connection refused')
